type NullableAnalysisSummary struct {
	value *AnalysisSummary
	isSet bool
}

func (v NullableAnalysisSummary) Get() *AnalysisSummary {
	return v.value
}

func (v *NullableAnalysisSummary) Set(val *AnalysisSummary) {
	v.value = val
	v.isSet = true
}

func (v NullableAnalysisSummary) IsSet() bool {
	return v.isSet
}

func (v *NullableAnalysisSummary) Unset() {
	v.value = nil
	v.isSet = false
}

func NewNullableAnalysisSummary(val *AnalysisSummary) *NullableAnalysisSummary {
	return &NullableAnalysisSummary{value: val, isSet: true}
}

func (v NullableAnalysisSummary) MarshalJSON() ([]byte, error) {
	return json.Marshal(v.value)
}

func (v *NullableAnalysisSummary) UnmarshalJSON(src []byte) error {
	v.isSet = true
	return json.Unmarshal(src, &v.value)
}
